static void merge(int* a, size_t left, size_t mid, size_t right) {
    size_t n1 = mid - left;
    size_t n2 = right - mid;
    int* L = (int*)malloc(n1 * sizeof(int));
    int* R = (int*)malloc(n2 * sizeof(int));
    for (size_t i = 0; i < n1; ++i) L[i] = a[left + i];
    for (size_t j = 0; j < n2; ++j) R[j] = a[mid + j];
    size_t i = 0, j = 0, k = left;
    while (i < n1 && j < n2) {
        if (L[i] <= R[j]) { a[k++] = L[i++]; }
        else { a[k++] = R[j++]; }
    }
    while (i < n1) a[k++] = L[i++];
    while (j < n2) a[k++] = R[j++];
    free(L);
    free(R);
}

